settings.html:
[stillness_past_events_counter]

<style>
@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,300;0,400;0,500;1,300;1,400&family=Jost:wght@300;400;500&display=swap');

:root {
  --ec-seafoam: #688F9D;
  --ec-stone: #0E1B30;
  --ec-warm: #F2E8DF;
}

.ec-counter-ribbon {
  background: var(--ec-warm) !important;
  padding: 1.25rem 4rem 0 !important;
  text-align: center !important;
  border-bottom: 0.5px solid rgba(14,27,48,0.06) !important;
}

.ec-counter-content {
  display: inline-flex !important;
  align-items: center !important;
  gap: 1.2rem !important;
}

.ec-counter-num {
  font-family: 'Cormorant Garamond', serif !important;
  font-size: 2.5rem !important;
  font-weight: 300 !important;
  color: var(--ec-seafoam) !important;
  line-height: 1 !important;
}

.ec-counter-text {
  font-family: 'Jost', sans-serif !important;
  font-size: 0.75rem !important;
  letter-spacing: 0.25em !important;
  text-transform: uppercase !important;
  color: var(--ec-stone) !important;
  font-weight: 500 !important;
  padding-top: 0.25rem !important;
}

.ec-reveal {
  opacity: 0 !important;
  transform: translateY(24px) !important;
  transition: opacity 0.8s ease, transform 0.8s ease !important;
}

.ec-reveal.ec-visible {
  opacity: 1 !important;
  transform: translateY(0) !important;
}

@media(max-width: 768px) {
  .ec-counter-ribbon {
    padding: 0.75rem 1.5rem 0 !important;
  }
  .ec-counter-num {
    font-size: 2rem !important;
  }
}
</style>

<script>
  setTimeout(() => {
    const observerOptions = { root: null, rootMargin: '0px', threshold: 0.15 };
    const observer = new IntersectionObserver((entries, obs) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('ec-visible');
          obs.unobserve(entry.target);
        }
      });
    }, observerOptions);
    document.querySelectorAll('.ec-counter-ribbon').forEach(element => {
      observer.observe(element);
    });
  }, 500);
</script>
